    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Un flag di funzionalità è un’impostazione che le app valutano per una persona in un’organizzazione. Attivalo per utenti o organizzazioni specifici oppure per una percentuale di tutti gli utenti. Ogni app riceve la stessa risposta dal claim `feature_flags` del token o dall’endpoint di valutazione, senza un nuovo rilascio. Una regola utente prevale su una dell’organizzazione, poi sulla distribuzione graduale e infine sul valore predefinito.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Una chiave consente a script e integrazioni di chiamare l’API di un’app a tuo nome senza effettuare l’accesso. Può fare solo ciò che puoi fare tu nell’app. Se i tuoi diritti si riducono, anche la chiave li perde. Viene mostrata una sola volta: copiala alla creazione e revocala subito se viene divulgata o non è più usata.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Un’autorizzazione permette a un ruolo di eseguire un’azione, come creare fatture o leggere report. Puoi definirne di tue qui senza codice e comporle in ruoli. Le app possono anche registrare automaticamente le proprie, così l’elenco riflette i controlli effettivi. Puoi modificare le tue autorizzazioni; quelle condivise dall’ambiente si possono usare ma non modificare.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Un telefono con l’app di autenticazione risponde alle richieste di approvazione e segnala gli accessi a tuo nome. Registralo scansionando il codice. Se perdi il telefono, rimuovilo subito qui: non potrà più approvare nulla.',
    'a_project_is_one_idp_product_this_workspace_owns_and_it_a5e40dff' => 'Un progetto è un prodotto di provider di identità appartenente allo spazio di lavoro, a cui sono collegati gli ambienti. Finché lo spazio di lavoro non ne crea uno dalla propria console, qui non c’è nulla da selezionare o aprire. Questa schermata non crea progetti per conto dello spazio di lavoro.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Un progetto è uno dei tuoi prodotti, con piano, accesso e ambienti propri, come produzione e staging. Apri un ambiente da qui per amministrarlo. Crea un progetto quando lanci un prodotto che deve funzionare ed essere fatturato separatamente.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Un ruolo è una funzione compresa dalle app, come redattore o addetto all’assistenza. Assegni i ruoli qui e ogni app decide cosa consentono. I ruoli accompagnano la persona nelle app collegate, così puoi concedere e revocare l’accesso da un unico posto.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Una revisione permette di verificare chi ha quali ruoli e se servono ancora. Gli accessi si accumulano quando le persone cambiano team e mantengono vecchie autorizzazioni. La revisione aiuta a rimuoverle. Le revoche si applicano alla chiusura e l’intero processo viene documentato per l’auditor.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Uno schema descrive gli eventi di un’azione: tipi di destinazione e metadati previsti. Gli eventi con schema vengono verificati all’arrivo. Senza schema vengono accettati così come sono, salvo che sia attiva la modalità rigorosa.',
    'a_workspace_is_one_signed_up_company_s_home_on_this_ins_3053f712' => 'Uno spazio di lavoro è l’area di un’azienda registrata su questa installazione, con progetti, ambienti e team. Aprilo per amministrarli. La sospensione disconnette i membri e interrompe gli accessi in tutti i suoi ambienti.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Gli accessi si accumulano. Le persone cambiano team e conservano vecchi diritti finché un auditor non se ne accorge. Una revisione fotografa le assegnazioni attuali e richiede una decisione, per ciascuna, sulla loro necessità.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Aggiungi la persona a un’organizzazione qui sotto per darle accesso al suo interno. Se le app non hanno separazione per cliente, puoi invece assegnare un ruolo di amministrazione e assistenza valido in tutto l’ambiente.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Un ruolo di amministrazione e assistenza viene assegnato al tuo personale, per esempio supporto e operations, in tutto l’ambiente. Si applica a ogni organizzazione senza che i suoi amministratori possano vederlo, assegnarlo o rimuoverlo. Un ruolo di un’app assegnato in questo modo resta limitato a quell’app.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Un ruolo di amministrazione e assistenza viene assegnato al tuo personale in tutto l’ambiente. Si applica a ogni organizzazione e i suoi amministratori non possono vederlo né modificarlo.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Un agente è un software che opera nell’ambiente con una chiave di gestione: un assistente IA come Claude Code o Cursor, un bot interno o il tuo backend. Assegna a ciascuno una chiave propria con i soli ambiti necessari. Scegli quali azioni richiedono approvazione e revoca la chiave appena il lavoro termina o qualcosa sembra anomalo.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Un’API è un tuo servizio che riceve token di accesso, come https://api.example.com. Registrala con gli ambiti che riconosce. Decidi quali possono essere richiesti dalle app registrate dalle organizzazioni. Un token per l’API include il suo indirizzo come destinatario, che il servizio verifica.',
    'an_environment_is_a_fully_isolated_identity_service_wit_fed9a3d8' => 'Un ambiente è un servizio di identità completamente isolato con utenti, chiavi, accesso ed emittente propri. Qui sono elencati tutti quelli dell’installazione con il relativo spazio di lavoro. Crea un ambiente, selezionalo nella console e configura la prima organizzazione e l’amministratore.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Un ambiente è completamente isolato, con utenti, chiavi, accesso ed emittente propri. Crea il primo qui sopra, poi configura un’organizzazione e un amministratore.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Un provider di identità che importa i metadati del fornitore di servizi usa questo URL invece di inserire separatamente ID entità e URL ACS. Funziona già prima di completare i dati del provider di identità.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Un’organizzazione raccoglie utenti, metodi di accesso e ruoli. Creane una qui sopra oppure configura la prima organizzazione e il suo amministratore dalla schermata Ambienti.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Il provider dell’organizzazione sostituisce quello dell’ambiente nella sua pagina di accesso. Compaiono anche i provider ereditati disattivati. Questo rimuove solo il pulsante: è l’obbligo di SSO a impedire gli altri metodi di accesso.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Le chiavi API e i token necessari alle app e agli agenti per altri servizi vengono archiviati cifrati qui, anziché nelle singole configurazioni. Inserisci un segreto una volta e autorizza app specifiche a usarlo. Non viene più mostrato: rinnovalo se lo perdi.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Le chiavi API usate dalle app e dagli agenti presso altri servizi. Ogni valore viene archiviato cifrato, fornito solo alle app autorizzate e non più mostrato dopo il salvataggio.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'App che chiedono di agire a nome dei tuoi utenti. Ogni utente approva le proprie richieste. Rifiuta qui solo quelle che sembrano abusive: il rifiuto viene registrato nel registro di controllo.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Le app con elenchi propri di utenti perdono la sincronizzazione appena qualcuno entra o esce. Una connessione SCIM trasmette subito ogni modifica, comprese le uscite che spesso vengono dimenticate.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID invia un messaggio firmato all’endpoint dopo un evento, come l’ingresso di un membro o un cambio di ruolo. I sistemi possono reagire senza interrogazioni periodiche. Gli invii vengono ritentati se necessario. L’endpoint viene informato dopo l’evento e non può modificarne l’esito.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Conferma gli accessi ancora necessari e revoca gli altri. Nulla viene applicato prima della chiusura. Un ruolo di amministrazione e assistenza revocato viene allora rimosso in tutte le organizzazioni contemporaneamente.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Scegli SCIM se il provider ci invia i dati, Google Workspace o Entra se dobbiamo recuperarli, oppure il tuo sistema HR, come Workday, BambooHR, Rippling, HiBob o Personio, per creare gli account alla data di ingresso.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code apre il browser per accedere qui e chiede cosa vuoi consentire. Non c’è una chiave da custodire. Qualsiasi client MCP con accesso OAuth funziona allo stesso modo con questo URL.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Separa con virgole o spazi. Un ambito inserito non ha un’API proprietaria e arriva invariato nei token dell’app. Non può mai indicare il destinatario di un’API registrata: per questi usa gli elenchi sopra.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Creare, modificare, attivare, disattivare ed eliminare connessioni SSO, richiedere SSO per un’organizzazione e verificare i domini email e attivarne l’instradamento SSO. Modifica il modo in cui le persone accedono.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Crea l’organizzazione, il proprietario, il primo prodotto e il suo ambiente di produzione. Il proprietario riceve via email un link per impostare la propria password: non ne scegli una al suo posto.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Definire, sostituire ed eliminare gli schemi di validazione degli eventi di controllo e modificarne la conservazione. Una durata più breve elimina definitivamente gli eventi più vecchi.',
    'deleting_this_workspace_tears_down_every_project_and_en_f26b2e2f' => 'Eliminare questo spazio di lavoro elimina tutti i suoi progetti e ambienti. Per proteggere i provider di identità attivi, l’operazione non è disponibile in autonomia. Contatta l’assistenza per procedere.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Ogni organizzazione è un’azienda o un team che usa il prodotto, con membri, ruoli, domini e SSO propri. Creane una per ogni azienda che si registra. Aprila per gestire membri, inviti e domini verificati o per sospenderla.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Ogni pipeline permette alle persone di collegare il proprio account presso servizi come GitHub, Google o Slack. I token vengono archiviati cifrati e mantenuti aggiornati qui. Le app autorizzate richiedono un token valido quando chiamano il servizio a nome della persona, senza archiviarlo.',
    'each_project_in_your_workspace_has_its_own_plan_and_env_c5ff35b1' => 'Ogni progetto dello spazio di lavoro ha il proprio piano e la propria quota di ambienti. Sono mostrati insieme all’utilizzo mensile: organizzazioni, connessioni SSO fatturate e accessi. Il prezzo considera utenti attivi mensili e connessioni aziendali come SSO e SCIM. Gli ambienti sandbox non hanno costi di connessione.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Tutto l’ambiente: chiunque abbia un account in questo ambiente può accedere all’app, indipendentemente dall’organizzazione. Seleziona un’organizzazione se non è ciò che intendi.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Cancellare definitivamente una persona (GDPR, art. 17): credenziali, sessioni, appartenenze e dati personali vengono eliminati e l’account pseudonimizzato. Non si può annullare.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Ordine di valutazione: elenco dei bloccati, elenco dei consentiti, le tue regole dall’alto con decisione alla prima corrispondenza, poi quelle integrate, dove prevale la più restrittiva applicabile. Senza corrispondenze, l’accesso è consentito.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Ogni azione viene accettata come inviata dall’app. Aggiungi uno schema per verificare gli eventi all’arrivo. La coerenza del registro si garantisce alla scrittura, non alla lettura.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Ogni modifica amministrativa a membri, ruoli, connessioni e app viene registrata qui appena avviene, con autore e data. Non serve alcuna configurazione.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Le chiavi API nelle configurazioni o nei file d’ambiente non si possono rinnovare centralmente né revocare rapidamente. Qui sono cifrate, concesse per app e revocabili con un clic.',
    'every_api_key_the_people_in_this_organization_have_crea_15e73625' => 'Tutte le chiavi API create dalle persone dell’organizzazione per le sue app. Revoca quelle divulgate o non più usate. Ogni persona crea le proprie chiavi in Il mio account.',
    'every_api_key_the_people_in_this_organization_have_crea_fe7787a7' => 'Tutte le chiavi API create dalle persone dell’organizzazione: titolare, app, autorizzazioni e ultimo utilizzo. Una chiave non ha più diritti del titolare e smette di funzionare quando questi lascia l’organizzazione. Revoca chiavi divulgate o inutilizzate. Ognuno crea le proprie in Il mio account.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Ogni app che autentica persone tramite Cbox ID o chiama la sua API viene registrata qui e riceve credenziali proprie. Registrane una per app e ambiente. Non condividere credenziali tra loro, così puoi revocarne una senza compromettere le altre.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Tutti i browser e dispositivi connessi al tuo account, le app autorizzate ad agire per te e gli ultimi accessi e cambiamenti di sicurezza. Se non riconosci qualcosa, termina la sessione o revoca l’accesso dell’app, poi cambia password.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Ogni modifica nell’organizzazione: chi ha fatto cosa, su quale elemento e quando. Gli hash delle voci sono concatenati: modificare o eliminare una voce rompe la catena e rende la modifica rilevabile. Il registro è volutamente in sola lettura e costituisce la documentazione per l’auditor.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Tutte le connessioni tra Cbox ID e altri sistemi in un unico posto: SSO, accesso social, sincronizzazione directory e HR, provisioning in uscita, app SAML, webhook, hook, flussi di log e pipeline. Ogni scheda del catalogo apre la configurazione appropriata. Connessioni elenca quelle esistenti con lo stato, mostrando prima gli errori.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Tutte le organizzazioni dell’ambiente selezionato nella console, in un albero di rivenditori, organizzazioni gestite e sottounità. Crea o sospendi un’organizzazione, oppure spostala sotto un’altra organizzazione superiore.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Tutte le pagine aperte da ora in poi, come Organizzazioni, Utilizzo o dettagli dell’organizzazione, leggono questo ambiente. Nessuno dei due ambienti viene modificato.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Tutte le persone con un’identità nell’ambiente, indipendentemente dalle organizzazioni. Aprine una per reimpostare password o secondo fattore, terminare sessioni, disattivare l’account, cambiare organizzazioni e ruoli o cancellarla definitivamente su richiesta.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Tutte le revoche registrate nella revisione vengono applicate ora. Gli elementi non esaminati seguono i criteri della revisione, che per impostazione predefinita revocano l’accesso. Questa operazione non può essere annullata.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Tutti i segreti che attualmente autenticano l’app. Di ciascuno viene archiviato solo un hash. L’elenco mostra gli ultimi quattro caratteri per identificare quello usato da una distribuzione.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Tutti i token emessi vengono revocati e nessun nuovo accesso può usarlo. Le app che verificano autonomamente i token li accettano fino alla scadenza, al massimo fino alla fine della sessione.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Tutti i metodi di accesso con il loro stato e dove modificarli: password, passkey, link via email, accesso social, Enterprise SSO e secondo fattore. L’ambiente controlla la maggior parte; ogni organizzazione gestisce le proprie connessioni SSO. Le restrizioni della distribuzione sono indicate con il nome dell’impostazione.',
    'every_workspace_on_this_install_open_one_to_walk_its_pr_4abbea51' => 'Tutti gli spazi di lavoro dell’installazione. Aprine uno per gestire prodotti e ambienti. La sospensione disconnette i membri e interrompe l’autenticazione in tutti i suoi ambienti.',
    'everyone_who_administers_this_workspace_the_built_in_ro_26825e5f' => 'Tutte le persone che amministrano lo spazio di lavoro, il ruolo predefinito (Proprietario, Amministratore, Sviluppatore, Membro o Lettore) e gli ambienti accessibili. Invita via email e concedi solo gli ambienti necessari al lavoro di ciascuno.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Tutte le persone che possono accedere all’organizzazione e gli inviti non ancora accettati. Invita via email: ognuno configura il proprio accesso, senza che tu debba gestirne la password.',
