    '_part1_entries_are_append_only_and_hash_chained_any_tam_9a24349b' => ':part1 Le voci possono solo essere aggiunte e i loro hash sono concatenati. Qualsiasi alterazione interrompe la catena.',
    '_part1_every_name_it_uses_is_defined_and_nothing_subtra_9ef8bb73' => ':part1 Tutti i nomi usati sono definiti e nessuna relazione sottrae sé stessa.',
    '_part1_found_c872536b' => 'Risultati trovati: :part1.',
    '_part1_from_the_environment_is_no_longer_offered_on_thi_2b5c99c4' => ':part1 dell’ambiente non è più disponibile nella pagina di accesso dell’organizzazione.',
    '_part1_from_the_environment_is_offered_on_this_organiza_d3320a78' => ':part1 dell’ambiente è di nuovo disponibile nella pagina di accesso dell’organizzazione.',
    '_part1_has_its_own_rules_2979eb4e' => ':part1 ha regole proprie.',
    '_part1_hex_ac7233c8' => 'Valore esadecimale di :part1',
    '_part1_is_a_sign_in_scope_cbox_id_defines_itself_so_no_25cd6511' => '«:part1» è un ambito di accesso definito da Cbox ID, quindi non può appartenere a un’API.',
    '_part1_is_already_set_up_for_the_environment_change_its_57ef8e6e' => ':part1 è già configurato per l’ambiente. Modifica le credenziali oppure rimuovilo prima.',
    '_part1_is_not_a_scope_no_spaces_quotes_or_backslashes_5acfdc43' => '«:part1» non è un ambito valido: spazi, virgolette e barre inverse non sono ammessi.',
