    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Un codice può essere rubato tramite sostituzione fraudolenta della SIM o portabilità non autorizzata del numero, intercettato nella rete telefonica o inserito in una pagina di accesso falsa ma convincente. Resta comunque molto più sicuro della sola password. Attivalo per chi non può usare un’app di autenticazione o una passkey.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Un logo caricato da un altro sito rivelava a quel sito chi apriva la tua pagina di accesso. Per questo le pagine ospitate ora mostrano solo immagini caricate qui. Caricalo sotto :part2 qui sotto oppure rimuovilo per eliminare questo avviso.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Un ruolo è un’etichetta inserita nel token. I ruoli dichiarati da un’app sono di sola lettura qui; gli altri li definisci tu. Ogni membro ha anche esattamente un :part2 :part3 :part4 (proprietario, amministratore, sviluppatore, membro o lettore), che stabilisce cosa può amministrare in questa console.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '«:part1» appartiene già a un’altra API in questo ambiente. Una richiesta di token identifica un ambito solo tramite la sua chiave, quindi ogni chiave può appartenere a una sola API.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 appartengono a un’API che questa app non può usare. Vengono esclusi da tutti i token; rimuovili dagli ambiti inseriti.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 possono accedere con le password o con questa connessione. Rendere obbligatorio il Single Sign-On rifiuta ogni altra modalità di accesso, affinché nemmeno gli accessi già emessi possano aggirare il provider appena configurato. La maggior parte delle aziende che collega un IdP desidera questo comportamento, ma prima leggi cosa comporta.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 non ha ancora autorizzazioni, quindi :part2 :part3 è vuoto. Il nome del ruolo rimane disponibile e può essere utilizzato.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 è già configurato per questa organizzazione. Modifica le credenziali oppure rimuovi prima la connessione.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 non è più disponibile. Chi lo ha usato conserva il proprio account e può continuare a usare la password.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 è disattivato su tutte le pagine di accesso. Le credenziali vengono conservate per consentirti di riattivarlo.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 è disattivato sulla pagina di accesso di questa organizzazione. Le credenziali vengono conservate per consentirti di riattivarlo.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 è il tuo unico modo per accedere. Imposta una password o aggiungi una passkey prima di scollegarlo.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 è il Single Sign-On della tua organizzazione. È il modo in cui l’organizzazione ti identifica, quindi non può essere scollegato qui.',
    '_part1_its_team_is_administered_under_workspace_team_by_939d535a' => ':part1 Il team viene amministrato in Area di lavoro › Team da una persona con un ruolo nell’area di lavoro, non da qui.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Nulla qui è ancora definito da :part3. Qualsiasi modifica qui sotto diventa una regola propria di questa organizzazione.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 aggiornati, :part3 deprovisionati,:part4 :part5 ignorati, :part6 gruppi :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Aggiorna prima il ricevitore: dal prossimo tentativo rifiuterà tutte le consegne che non riesce a verificare.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 rifiuta l’accesso se questo valore non corrisponde esattamente. Viene conservato per questa configurazione, quindi puoi incollarlo ora in :part2 e salvare qui in seguito.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1: sessioni, passkey e secondi fattori, profili presso i provider di identità, dati di directory, token emessi, assegnazioni di ruoli e cronologia di audit vengono conservati e possono essere riattivati.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Tutto ciò che la tua organizzazione ha configurato e ciò che resta da fare. La lista di configurazione riflette lo stato reale: ogni passaggio viene contrassegnato automaticamente come completato appena è stato eseguito.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Tutta l’identità visiva del tuo prodotto in una pagina: logo, favicon, colori, carattere e angoli della pagina di accesso ospitata, con anteprima in tempo reale, oltre a nome del prodotto, mittente delle e-mail e messaggio di benvenuto. Configurala una volta per l’intero ambiente e ogni organizzazione la erediterà. Puoi anche personalizzare una singola organizzazione dalla sua scheda Identità visiva.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Dal prossimo tentativo, i blocchi impediranno gli accessi e le registrazioni in questo ambiente, mentre i controlli richiederanno una verifica aggiuntiva. Una regola errata può impedire l’accesso a persone reali.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Concederne uno alle persone che supportano o eseguono le vostre applicazioni. Il ruolo di un\'app raggiunge solo i token di quell\'app; un ruolo per tutte le applicazioni raggiunge ognuno di loro.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Il numero di organizzazioni, utenti, connessioni SSO, app e sincronizzazioni utenti presenti in questo ambiente, con i link alle rispettive pagine. I collegamenti rapidi sottostanti permettono di creare gli elementi più comuni: un’organizzazione, un utente, una connessione SSO o un’app.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Il numero di persone che hanno effettuato l’accesso e la frequenza delle chiamate delle tue app all’API negli ultimi 30 giorni. Questa vista aiuta a valutare il carico e individuare anomalie. Non è una fattura.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'La frequenza di recupero dei dati e i campi del sistema HR da copiare per ogni persona, come il centro di costo o la sede. Se modifichi i campi, la prossima sincronizzazione sarà completa.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Come vengono esportati i log di audit da Cbox ID: un’esportazione pianificata invia le nuove voci al tuo SIEM o archivio ogni cinque minuti. Un’attività giornaliera di conservazione crea un punto di controllo del log senza eliminare nulla. Qui puoi recuperare la cronologia di audit di una persona per rispondere a una richiesta di accesso ai sensi del GDPR oppure verificare, nella console di un ambiente, che le esportazioni funzionino.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Se l’app dichiara in seguito un URL diverso, l’approvazione viene revocata e ti viene richiesta di nuovo. La destinazione a cui vengono inviate le password non deve cambiare senza il tuo consenso. L’accesso delegato agevola la transizione: quando rimangono poche persone sul vecchio sistema, disattivalo e invia loro un link per reimpostare la password.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Il pulsante scompare e le credenziali vengono eliminate. Chi ha usato questa connessione conserva il proprio account e può continuare a usare la password. Per conservare le credenziali, disattiva invece la connessione.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Anche i suoi ambiti vengono eliminati. Le app che li avevano li conservano come ambiti inseriti che non danno più accesso a questa API. I token già emessi continuano a funzionare fino alla scadenza.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Chiavi dell’API di gestione di un ambiente: amministra le sue organizzazioni, i membri, gli inviti, i ruoli e le app dal tuo backend. Ogni chiave ha ambiti definiti esplicitamente.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Le chiavi create dagli utenti di questa organizzazione per le sue app, con le autorizzazioni di ciascuna. Gli utenti creano le proprie chiavi. Revoca quelle che sono state esposte o non vengono più usate.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Lascia il campo vuoto per quasi tutti i provider: i loro token ID vengono verificati con le chiavi di firma pubblicate nel documento di discovery (jwks_uri), anche dopo una rotazione. Incolla la chiave pubblica PEM del provider solo se non pubblica alcuna chiave.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Consenti l’accesso con un account già esistente. Configura un provider una volta per l’ambiente e tutte le organizzazioni lo offriranno. Un’organizzazione può invece usare credenziali proprie o disattivare un provider.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Consenti agli utenti delle tue app di collegare i propri account GitHub, Google, Slack o Salesforce, affinché le app possano chiamare queste API per loro conto. I token vengono archiviati in forma crittografata, rinnovati qui e resi temporaneamente disponibili solo alle app che autorizzi.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Consente ai tuoi utenti di accedere con il proprio account aziendale Microsoft Entra ID, Okta o Google Workspace, invece di usare una password separata qui. Collega il provider di identità e verifica i domini e-mail una sola volta. Tutte le persone che usano questi domini verranno poi indirizzate al provider per accedere.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'L’accesso con Entra ID, Okta o Google Workspace è disponibile nel piano Enterprise. Contatta il tuo referente commerciale per abilitarlo per questa organizzazione.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'I link ancora validi consegnati all’amministratore IT di questa organizzazione. Se ne revochi uno, smette subito di funzionare. Le configurazioni già eseguite tramite quel link vengono conservate.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Cerca un’organizzazione per nome o identificativo breve, oppure un utente per nome o e-mail, in tutti gli ambienti di questa installazione e non solo in quello aperto nella console. Usa la ricerca quando qualcuno chiede aiuto e non sai in quale ambiente si trova.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Gli schemi dei metadati usano un sottoinsieme di JSON Schema: un oggetto con proprietà di tipo stringa, numero, intero, booleano o null e regole per valori ammessi, lunghezza, intervallo, pattern e formato. Salvare una modifica crea una nuova versione. Gli eventi già registrati mantengono la versione con cui sono stati convalidati.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Invia ogni nuova voce del log di audit agli strumenti del team di sicurezza, come un SIEM, appena viene registrata. Configura il flusso per iniziare le indagini negli strumenti già usati dal team, senza richiedere prima un’esportazione. La consegna avviene almeno una volta, quindi possono esserci duplicati occasionali.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Per la maggior parte delle integrazioni sono più adatti i webhook: vengono eseguiti dopo l’evento e non possono bloccare il processo. Usa un hook solo quando il tuo sistema deve intervenire durante un accesso o l’emissione di un token.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Non viene emesso un nuovo segreto. Dal prossimo tentativo, inclusi i tentativi ripetuti, le consegne useranno gli header dell’altro metodo. Un ricevitore non aggiornato le rifiuterà tutte.',
    'nobody_is_on_this_workspace_it_has_no_owner_so_nobody_c_554101fb' => 'Questo spazio di lavoro non ha membri né proprietario, quindi nessuno può accedere per amministrarlo. È un errore di provisioning da verificare, non semplicemente un elenco vuoto.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Nessuna voce viene sempre rifiutata o esentata dalle regole. Blocca un intervallo di indirizzi da cui hai ricevuto attacchi oppure esenta la rete dell’ufficio dalle regole sulla frequenza di accesso.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Mostra Google, GitHub, Apple e altri provider come pulsanti nella pagina di accesso, per chi preferisce usare un account esistente anziché creare un’altra password. Configura un provider una volta per l’ambiente e tutte le organizzazioni lo offriranno. Un’organizzazione può usare credenziali proprie o disattivare un provider. Tu fornisci le credenziali; il resto viene compilato automaticamente. Un indirizzo e-mail comunicato da un provider non basta mai da solo per accedere a un account già presente qui.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Attivo per questa percentuale delle persone a cui non si applicano le regole precedenti. Un hash stabile dell’ID utente seleziona sempre le stesse persone; aumentare la percentuale ne aggiunge soltanto altre. Lascia vuoto se non vuoi un rilascio graduale.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Un evento contrassegnato (siem.stream.test) viene inviato ora con le impostazioni e le credenziali di questo flusso, senza accodamento né nuovi tentativi. Un invio riuscito rimuove anche l’indicazione «Azione richiesta».',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'Una voce per riga, incluso il protocollo, per esempio https://app.example.com. Se una riga non è valida, viene rifiutato l’intero elenco. Le righe errate non vengono eliminate senza avviso.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'Un `type` per tipo di risorsa, con le relative voci `relation` sotto. Una relazione è determinata dai soggetti nominati direttamente in una tupla ([user, group#member]), da un’altra relazione (owner), da una relazione su una risorsa superiore (viewer from parent) o da una combinazione con or, and o but not.',
    'one_workspace_on_this_install_its_team_its_projects_and_e343ed1c' => 'Uno spazio di lavoro di questa installazione, con il team, i progetti e tutti gli ambienti dei progetti. Sospenderlo disconnette i membri e interrompe l’autenticazione in tutti questi ambienti.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Solo per un provider che non pubblica le chiavi di firma (jwks_uri) nel documento di discovery. Altrimenti le chiavi vengono recuperate da lì, anche dopo una rotazione. Inserisci una chiave pubblica PEM. Viene archiviata in forma crittografata e non viene più mostrata. Lascia vuoto per mantenere la chiave attuale.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Solo i membri attivi dell’organizzazione scelta possono accedere a questa applicazione. Tutti gli altri vengono rifiutati e il rifiuto viene registrato nel log di audit.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'I dettagli dell’organizzazione nell’ambiente di destinazione: membri, SSO, domini, diritti assegnati e attività recente. In questa pagina è possibile modificare solo lo stato dell’organizzazione.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organizzazioni, utenti e sessioni attive di tutti gli ambienti di questa installazione, oltre alle organizzazioni con più membri. Questa vista legge soltanto i dati e non cambia mai l’ambiente selezionato nella console.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Scegli il framework che usi e verrà creata un’app con reindirizzamento al server di sviluppo locale, variabili d’ambiente da copiare e codice di accesso. La pagina attende che qualcuno acceda davvero. Sotto trovi i passaggi per trasformarla in un prodotto: identità visiva, organizzazioni, SSO, un agente, un collega e produzione. Ogni passaggio viene contrassegnato automaticamente in base allo stato reale dell’ambiente, mai a mano.',
    'platform_operators_administer_every_workspace_and_envir_fb24c050' => 'Gli operatori della piattaforma amministrano tutti gli spazi di lavoro e gli ambienti di questa installazione da un livello superiore. Aggiungi come operatore solo chi gestisce l’installazione stessa e sospendine l’accesso appena questo compito non gli compete più.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Collega un provider di identità al nostro endpoint SCIM, collega Google Workspace o Microsoft Entra, oppure connetti il tuo sistema HR: Workday, BambooHR, Rippling, HiBob o Personio. Recupereremo i dati delle persone dai sistemi collegati a intervalli programmati.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Verifica quali domini e-mail appartengono alla tua organizzazione. Un dominio verificato può indirizzare tutte le persone con un indirizzo su quel dominio direttamente alla connessione SSO aziendale.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar valuta ogni accesso e registrazione: tentativi con credenziali rubate, velocità tipica dei bot, spostamenti geograficamente impossibili, nuovi dispositivi, reti di anonimizzazione e indirizzi usa e getta, oltre alle tue regole e liste di autorizzazione e blocco. Registra ogni decisione. Quando attivi l’applicazione delle regole, Radar blocca l’accesso o richiede un secondo fattore. Esamina qui le decisioni prima di attivarla e quando qualcuno segnala di non riuscire ad accedere.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar valuta ogni accesso e registrazione: tentativi con credenziali rubate, velocità tipica dei bot, spostamenti geograficamente impossibili, nuovi dispositivi, reti di anonimizzazione e indirizzi usa e getta, oltre alle tue regole e liste. Registra i motivi di ogni decisione.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Rifiutare le password presenti in violazioni di dati note. Il controllo usa Have I Been Pwned senza mai inviare la password. Se il servizio non è raggiungibile, la registrazione viene consentita anziché bloccata.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registra le applicazioni che accettano questo ambiente come provider di identità SAML. Gli utenti accedono con gli account che hanno già qui. Associa ogni applicazione alla sua organizzazione, così potranno accedere solo i membri. Senza associazione, è aperta a tutte le persone dell’ambiente. Questa è la direzione in uscita. Per consentire l’accesso con un account aziendale esterno, usa SSO aziendale in Autenticazione.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Le richieste appaiono qui automaticamente quando un’app o un agente necessita della tua approvazione per agire per tuo conto. Fino ad allora non devi fare nulla. Rifiuta le richieste che non hai avviato tu.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Le richieste degli agenti che vogliono agire per conto di un utente compaiono qui al loro arrivo. Ogni utente approva le proprie richieste. Questa pagina permette di rifiutare quelle che sembrano abusive.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Attualmente le persone accedono con credenziali conservate qui. Collega il provider affinché usino il proprio account aziendale esistente. Perderanno l’accesso qui appena disattiverai l’account presso il provider.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Gli ambiti, gli URI di disconnessione, le impostazioni dei token e l’URL del manifesto dei ruoli vengono copiati senza modifiche. Segreti, chiavi e utenti dell’app non vengono copiati: appartengono all’ambiente in cui sono stati creati.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Vedi l’app esattamente come uno dei suoi utenti: accedi a suo nome per il motivo indicato e per un massimo di un’ora. L’app conosce la tua identità reale e non riceve alcun modo per prolungare l’accesso. Il log di audit dell’organizzazione registra chi lo ha fatto e perché.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Invia questo link monouso a chi configura il tuo provider di identità. Scade a breve e funziona senza un account. Copialo ora: viene mostrato una sola volta.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Invia questo link monouso a chi gestisce il provider di identità dell’organizzazione, se non lo ha già ricevuto via e-mail. Funziona senza un account fino alla scadenza. Copialo ora: viene mostrato una sola volta.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Espone gli endpoint di identità di un ambiente su un dominio di tua proprietà, come login.example.com, invece che sul nostro. Dimostri la proprietà con un record DNS TXT. Configuralo se gli utenti devono vedere solo il tuo indirizzo durante l’accesso.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Imposta questo come policy di attendibilità del ruolo (IAM › Roles › Trust relationships). La piattaforma può assumere il ruolo solo presentando l’ID esterno di questo flusso. In questo modo nessun altro sulla piattaforma può indirizzare un flusso verso il tuo ruolo.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Gli accessi e le richieste che Cbox ID ha valutato come abbastanza rischiosi da segnalare, dai più recenti, con punteggio e motivazioni. Controlla questa vista dopo un aumento degli accessi non riusciti o quando qualcuno segnala un accesso che non ha effettuato.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Accessi, token emessi, nuovi utenti e attivazioni dell’autenticazione a due fattori, giorno per giorno negli ultimi 30 giorni, salvo un diverso periodo configurato. La pagina rimane vuota finché chi gestisce l’installazione non configura l’archiviazione dei dati di analisi.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Acquisisce un’istantanea di tutti i ruoli di amministrazione e supporto nell’intero ambiente, come elementi da certificare o revocare. La revoca rimuove il ruolo da tutte le organizzazioni contemporaneamente.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Software che opera in questo ambiente con una chiave di gestione: Claude Code, Cursor, un bot interno o il tuo backend. Ognuno dispone solo degli ambiti che hai assegnato e attende la tua approvazione per le azioni che hai scelto.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Alcuni ruoli non devono mai essere assegnati alla stessa persona: chi crea un pagamento non dovrebbe anche approvarlo. Definisci queste coppie qui. Cbox ID blocca le nuove assegnazioni che violerebbero la regola e mostra chi possiede già entrambi i ruoli.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF e Generic JSON sono ricevitori HTTP per cui si indica un URL. Datadog, Amazon S3 e Google Cloud Storage usano impostazioni proprie.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Parti dall’esempio dei documenti nelle cartelle: proprietari, editor e lettori, con i diritti di accesso della cartella ereditati da tutto il contenuto. Le tuple e le verifiche delle autorizzazioni richiedono prima uno schema.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Opzioni che le tue app consultano per una persona in un’organizzazione. Attiva una funzionalità per utenti o organizzazioni specifici, oppure per una percentuale di tutti gli utenti. Ogni app riceve la stessa risposta, nel token o tramite l’API.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'L’indirizzo che i token di questa API indicano come audience e che la tua API verifica. Non può essere cambiato in seguito, perché tutti i token già emessi contengono questo valore.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'La richiesta dell’agente viene rifiutata e l’agente non può agire per conto della persona. Il rifiuto viene registrato nel log di audit e non può essere annullato. L’agente deve presentare una nuova richiesta.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Gli eventi di audit che la tua app invia per ogni organizzazione servita: chi ha fatto cosa nel prodotto e quando. Vengono conservati in una catena di hash per organizzazione e mostrati ai rispettivi amministratori. Usa questa funzione quando un’organizzazione richiede il log di audit del proprio account. Definisci gli schemi per mantenere gli eventi coerenti.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Gli eventi di audit inviati dalla tua app per tutte le organizzazioni servite, dai più recenti. Gli eventi di ogni organizzazione formano una propria catena di hash.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Il log di audit è qui, mentre gli strumenti del team di sicurezza sono altrove. Un flusso invia loro ogni nuova voce appena viene registrata, così un’indagine non deve iniziare con una richiesta di esportazione CSV.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Il pulsante scompare dalla pagina di accesso dell’organizzazione. Il provider dell’ambiente non lo sostituisce. Le credenziali vengono conservate per consentirti di riattivare la connessione.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'Il limite massimo di accesso di questa app. Una restrizione ha effetto dal token successivo. Se un dispositivo o un agente richiede un ambito che rimuovi, la richiesta viene rifiutata anziché concedere meno autorizzazioni senza avviso.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'La destinazione ha rifiutato le impostazioni, per esempio per un bucket mancante o una regione o un sito errati. Non viene consegnato nulla finché non sono corrette. Le voci restano in attesa e non vengono eliminate.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'I domini e-mail di questa organizzazione, ciascuno verificato con un record DNS TXT. Dopo la verifica puoi imporre il reindirizzamento di tutte le persone con un indirizzo su quel dominio alla connessione SSO aziendale, al posto della password. Verifica quindi tutti i domini usati dagli utenti prima di affidarti all’SSO.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per_42243556' => 'Le chiavi che il tuo codice usa per chiamare Cbox ID, con una scheda per tipo. Una chiave segreta di gestione permette al backend di amministrare organizzazioni, membri, inviti, ruoli e app di un ambiente. Una chiave dello spazio di lavoro chiama la relativa API con un ruolo integrato. Una chiave pubblicabile si usa in un’app per browser e funziona solo dalle origini autorizzate. Le chiavi segrete e dello spazio di lavoro vengono mostrate una sola volta. Copiale quando le crei e revocale subito se vengono esposte.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'La direzione opposta: Cbox ID invia i tuoi utenti agli altri prodotti SaaS dell’azienda tramite i loro endpoint SCIM. Gestisci attivazione e rimozione degli accessi in un unico posto, invece di usare un pannello di amministrazione per ogni fornitore.',
    'the_name_of_your_workspace_which_your_projects_environm_3fa3245f' => 'Il nome del tuo spazio di lavoro, che contiene progetti, ambienti e team e viene mostrato in tutta la console. Eliminare uno spazio di lavoro arresta tutti i relativi ambienti di accesso. Per questo occorre richiederlo all’assistenza, anziché usare un pulsante.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Le regole delle password, il blocco dell’account e i requisiti di autenticazione a due fattori e SSO applicati a ogni accesso. Per l’intero ambiente si definiscono anche la disponibilità di passkey e link di accesso e la durata delle sessioni. L’ambiente stabilisce una base ereditata da ogni organizzazione. Le organizzazioni possono rendere più severe le regole delle password e dei due fattori, ma mai meno restrittive.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'I tuoi servizi che ricevono token di accesso e gli ambiti appartenenti a ciascuno. Decidi tu a chi assegnare gli ambiti di un’API registrata. Nessuno può limitarsi a inserirli in un’app per ottenere accesso alla tua API.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'L’intero ambiente offre questo provider su ogni pagina di accesso. Scegli un’organizzazione per configurare un provider proprio. Questo sostituirà quello dell’ambiente sulla pagina di accesso di quell’organizzazione.',
    'the_workspace_s_own_keys_for_the_workspace_api_list_pro_d42a9e3f' => 'Le chiavi dello spazio di lavoro per la relativa API: elencare progetti e ambienti, creare ambienti ed elencare e invitare membri del team. Ogni chiave ha un ruolo integrato.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Le sessioni e i token della persona vengono revocati. Passkey, secondi fattori, appartenenze, assegnazioni di ruoli, token API, segreti della cassaforte, dispositivi e tutte le copie archiviate dei suoi dati vengono eliminati. L’account viene conservato solo come record pseudonimizzato e disattivato. Le app che sincronizzano le persone da qui ricevono una richiesta di eliminazione. Il log di audit conserva l’ID opaco, non il nome o l’indirizzo e-mail.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Questi hook vengono eseguiti durante un’operazione, non dopo, e la risposta ne cambia l’esito. Il tuo endpoint può aggiungere informazioni a un token oppure rifiutare completamente un accesso. Intervengono direttamente nel processo, quindi un endpoint lento o non funzionante ha effetti immediati su chi cerca di accedere.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'La persona perde immediatamente l’accesso a tutte le pagine di piattaforma di questa installazione. Le sessioni esistenti smettono di funzionare alla richiesta successiva. Puoi riattivarla qui.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Questa azione non può essere annullata. Credenziali, appartenenze e dati personali vengono eliminati e l’account viene pseudonimizzato. Se la persona è l’unico proprietario di un’organizzazione, trasferisci prima la proprietà.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Questa installazione non ha chiavi Turnstile (CBOX_ID_TURNSTILE_SITE_KEY), quindi non è possibile attivare il controllo Turnstile. Per una registrazione segnalata viene invece verificato l’indirizzo e-mail.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Questo endpoint appartiene all’ambiente e viene eseguito per tutte le sue organizzazioni. È mostrato qui perché interviene nei tuoi accessi. Viene gestito dall’operatore.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Questo ambiente offre un server MCP accanto all’API REST. Collegaci un agente con una chiave di gestione: potrà eseguire solo ciò che gli ambiti della chiave consentono, con gli stessi controlli, approvazioni e log di audit della console.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Questo ambiente offre un server MCP, l’interfaccia standard per le chiamate agli strumenti degli assistenti IA, accanto all’API REST. Inserisci l’indirizzo e una chiave di gestione in Claude Code, Cursor o un altro client MCP. L’agente potrà eseguire solo ciò che gli ambiti della chiave consentono, con gli stessi controlli e log di audit della console.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Questo utente non può più accedere ad alcuna applicazione dell’ambiente. Le sessioni esistenti smettono di funzionare alla richiesta successiva. I dati vengono conservati e puoi riattivarlo in qualsiasi momento.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Questo utente possiede o amministra un’organizzazione. Non è possibile assumere l’identità di questi account, perché ciò potrebbe dare a un’altra persona il controllo duraturo dell’organizzazione.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Attualmente le persone vengono aggiunte e rimosse qui manualmente. Collega la directory che l’azienda usa già per automatizzare entrambe le operazioni, comprese le rimozioni che spesso vengono dimenticate.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Finché un’API non viene registrata, un ambito è solo testo nelle impostazioni di un’app. Chiunque possa modificare l’app può assegnarle qualsiasi ambito. Registra le API chiamate dalle tue app affinché i loro ambiti abbiano un proprietario.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'I domini verificati indirizzano le persone al tuo provider di identità. Questa funzione è inclusa nel piano Enterprise. Contatta il tuo referente commerciale per abilitarla per questa organizzazione.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Verificare un dominio di tua proprietà, come acme.com, permette a Cbox ID di riconoscere gli utenti dall’indirizzo e-mail e indirizzarli direttamente al provider. Nessuno deve così scegliere il pulsante di accesso corretto.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhook, notifiche di disconnessione alle app collegate, aggiornamenti dei ruoli recuperati dalle app ed e-mail in coda vengono elaborati in background dai worker di coda, senza far attendere la persona. Se nessun worker è attivo, nulla di questo viene elaborato, anche se il resto della console sembra normale. Questa pagina permette di individuare il problema.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Le azioni degli agenti di questo ambiente in attesa di approvazione. Se la chiave la richiede, l’agente si ferma e chiede alla persona che l’ha creata. La persona può rispondere dal telefono o qui. Chi amministra l’ambiente può rifiutare le richieste sospette. Sotto compaiono le richieste delle app che vogliono agire per conto di un utente; ogni utente approva le proprie.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Ciò che un’app può essere autorizzata a fare in questa API. Le tue app possono avere tutti questi ambiti. Quelle registrate da un’organizzazione possono avere solo gli ambiti abilitati per le organizzazioni.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Le azioni del software di questo ambiente in attesa di approvazione. Un agente la cui chiave la richiede si ferma e chiede alla persona che l’ha creata. Rispondi qui o dal telefono.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'La chiave richiesta dal tuo codice e contenuta nel claim feature_flags. Lettere minuscole e cifre, con - _ o . tra loro. Non può essere modificata in seguito.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Quando un’app o un agente IA necessita del tuo consenso per agire per tuo conto, non sempre può chiederlo sullo schermo che stai usando. Per questo la richiesta appare qui. Approva solo quelle che hai avviato e verifica che il codice corrisponda a quello sul dispositivo richiedente.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Quando TUTTE le condizioni sono soddisfatte, Radar esegue l’azione della regola e non valuta quelle successive. Queste regole vengono valutate dopo le liste di autorizzazione e blocco e prima delle regole integrate.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'La destinazione a cui Cbox ID invia le persone dopo la disconnessione da questa app. L’URI richiesto deve essere presente qui in modo identico, compresa l’eventuale barra finale. Altrimenti la persona rimane nella pagina di disconnessione di Cbox ID. Lascia vuoto se l’app non richiede mai un reindirizzamento di ritorno.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Dove hai effettuato l’accesso, cosa può agire per tuo conto e cosa è successo al tuo account. Se vedi una sessione che non riconosci, disconnettila e cambia la password.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Durante la migrazione da un altro sistema, l’app può dichiarare il vecchio endpoint di accesso nel manifesto, accanto ai ruoli. Compare qui per l’approvazione prima di essere utilizzato.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Durante la migrazione da un altro sistema, un’app può richiedere che l’e-mail e la password delle persone non ancora presenti in Cbox ID vengano verificate dal vecchio endpoint di accesso. Provalo prima di approvarlo. Le persone che accetta vengono create qui e non sono più inviate lì. Se l’endpoint non funziona, però, chi non è ancora migrato non può accedere.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Senza ruoli, chiunque possa accedere riceve i diritti che l’app assegna a un utente normale. Con i ruoli definisci una volta chi può modificare e chi fa parte dell’assistenza, per esempio, e tutte le app collegate possono rispettare questa suddivisione.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Crea una regola per consentire, richiedere una verifica aggiuntiva o bloccare in base a ciò che sai degli utenti. Per esempio, richiedi verifiche aggiuntive per accessi da paesi in cui non operate oppure esenta la rete dell’ufficio dalle regole sulla frequenza di accesso.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Agisci come questa persona, nella sua sessione e con i suoi diritti. L’accesso è limitato a 30 minuti ed è di sola lettura dove la console può imporlo. Ogni richiesta viene registrata a tuo nome.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Perdi l’accesso immediatamente. Come proprietario puoi lasciare l’organizzazione solo quando ne diventa proprietario qualcun altro. Trasferisci prima la proprietà oppure elimina l’organizzazione in Impostazioni.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Il modello di accesso della tua app: tipi di risorse come documenti e cartelle, relazioni come proprietario, editor e lettore e le relative regole di ereditarietà. Chi può leggere una cartella può leggere tutti i documenti al suo interno. L’app salva le relazioni tra persone e risorse e chiede a ogni richiesta: «questo utente può modificare questo documento?». Lo schema determina la risposta.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Il modello di accesso della tua app: tipi di risorse, relazioni di ciascun tipo e come vengono ereditate. L’app scrive tuple — chi è in relazione con cosa — e verifica i permessi a ogni richiesta.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'La tua app invia questi eventi con una chiamata per lotto. Ogni evento indica l’organizzazione in cui si è verificato. Compaiono qui e agli amministratori dell’organizzazione man mano che arrivano.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'L’identità visiva predefinita dell’ambiente: aspetto, logo e favicon dell’accesso ospitato, oltre al nome e al mittente mostrati agli utenti. Ogni organizzazione la eredita, a meno che non ne imposti una propria.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Il tuo provider di identità crea, aggiorna e disattiva automaticamente le persone qui tramite lo standard SCIM. Gli ingressi e le uscite registrati nel sistema HR raggiungono le app in pochi secondi, senza ticket né account dimenticati — un aspetto essenziale quando qualcuno lascia l’organizzazione.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'I tuoi metodi di accesso e le sessioni attive. Una passkey offre la protezione migliore ed è la più rapida da usare: il dispositivo la sblocca con l’impronta digitale o il riconoscimento facciale, senza password da rubare tramite phishing.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Il ricevitore conserva lo stesso segreto. Un segreto esadecimale di 64 caratteri diventa whsec_ seguito dalla codifica base64 della stringa — "whsec_" + base64(secret). Un segreto che inizia già con whsec_ viene usato senza modifiche.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => ':part1 attività consigliate, approssimativamente in questo ordine. Ogni attività viene contrassegnata automaticamente come completata appena è stata davvero eseguita. Non devi contrassegnare nulla manualmente.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "l’ID della persona",
  "org": "l’organizzazione per cui agisce",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'Una chiave API (Impostazioni organizzazione › Chiavi API), non una chiave dell’applicazione. Viene archiviata in forma crittografata e non viene più mostrata.:part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Come le persone si accedono a :part1. Questi iniziano come predefinito del vostro ambiente; qualsiasi cosa si cambia qui può solo renderli più rigorosi.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'I suoi membri sono firmati fuori e tutti :part1 che possiede smettere di servire auth sulla prossima richiesta. È possibile riattivarlo qui.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'I suoi :part1 sono firmati fuori e tutti i :part2 che possiede smettere di servire auth sulla prossima richiesta. È possibile riattivarlo qui.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'I suoi :part1 non possono più accedere a questa organizzazione e le app che si affidano a essa non possono più autenticarli. Le sotto-organizzazioni non vengono sospese insieme a essa. Puoi riattivarla qui.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minuti, al massimo :part1. Empty utilizza il :part2. Accorciamento termina anche sessioni più lunghe già in esecuzione.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Solo se la tua app ha bisogno di più da :part1 che l\'accesso non è separato da spazi. I campi di applicazione sono sempre richiesti.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Incolla l\'intero file chiave JSON di un account di servizio assegnato ruoli / storage.objectCreator sul secchio. Archiviato crittografato e mai più mostrato.:part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Gli ambienti Sandbox consentono URL di host locale e non inviano mai email reali. :part1 rimanenti sul piano di questo progetto.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Accedi ad una delle tue app come :part1 per vedere quello che vedono. L\'app viene detto che sei tu, e l\'organizzazione di registri di audit che, quando e perché.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'L\'app i cui ruoli dichiarati e permessi gettoni per questo trasporto API. Solo le applicazioni di proprietà di :part1 possono essere scelti.',
    'the_new_key_for_part1_copy_it_now_you_won_t_be_able_to_42e3ecb3' => 'La nuova chiave per :part1. Copiala ora: non potrai più visualizzarla.',
    'this_will_sign_people_out_of_part1_c2cac70c' => 'Questo disconnetterà le persone da :part1',
    'turn_off_part1_cdd28418' => 'Disattiva :part1',
    'turn_off_part1_on_this_page_e3c91b07' => 'Disattiva :part1 in questa pagina',
    'turn_on_part1_41acb93f' => 'Attiva :part1',
    'turn_on_part1_for_everyone_ef925d74' => 'Attiva :part1 per tutti',
    'until_part1_ca03d4b6' => 'fino a :part1',
    'use_your_environment_s_defaults_for_part1_c214943d' => 'Usare le impostazioni predefinite dell’ambiente per :part1?',
    'verify_part1_5e0158de' => 'Verifica :part1',
    'view_part1_ac7c77ab' => 'Visualizza :part1',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Ciò che un’app può essere autorizzata a fare in questa API. Solo le app di :part1 possono avere queste autorizzazioni.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Ciò che :part1 offre la pagina di accesso. I fornitori dell\'ambiente sono ereditati; questa organizzazione può spegnere uno, o impostare il proprio al suo posto.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Quando la chiave di un agente ha bisogno di approvazione per un\'azione, la richiesta appare qui e al telefono della persona che ha creato la chiave. Attende fino a :part1.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Quali modi in :part1 offre oltre a una password, e per quanto tempo un accesso dura. Questi sono gli stessi per ogni organizzazione in esso.',
    'withdraw_access_for_part1_10961483' => 'Revoca l’accesso dell’app :part1',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Il claim :part2 ha un significato diverso: indica ciò che la :part3 :part4 poteva richiedere, non ciò che questa :part5 può fare.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Non servono per accedere a questa console: gli amministratori accedono tramite Cbox ID su :part2, con i metodi di accesso disponibili lì.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Seleziona l’ambito :part2 :part3 quando registri l’app. Il token ID includerà gli stessi nomi dei ruoli nel claim :part4, il nome cercato da Kubernetes, Grafana e Vault. Non occorre creare altro.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Stai impersonando :part2 :part3 per fornire assistenza. Ogni tua azione viene registrata. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Una chiave di gestione agisce solo nel proprio ambiente. Esporta il blueprint di questa app (GET /apps/{id}/blueprint) e registralo con la chiave dell’altro ambiente (POST /apps con `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Una chiave di gestione per un singolo agente. Può fare solo ciò che i suoi ambiti consentono e le azioni che scegli attendono la tua approvazione, sul telefono o su :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Una pagina su :part1. Lascia vuoto per arrivare nella console, con :part2 indicato nell’invito.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Un :part1 è l’IdP di un singolo prodotto. Contiene :part2 :part3 isolati, produzione e sandbox, ciascuno con utenti, chiavi e accesso propri, ed è fatturato secondo il proprio piano.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Un’autorizzazione indica ciò che una :part1 può fare dopo l’accesso. Ciò che una :part2 può richiedere è invece un ambito, impostato durante la registrazione in :part3 :part4.',
    'a_workspace_key_reaches_the_workspace_itself_projects_e_28317ec8' => 'Una chiave dello spazio di lavoro accede allo spazio di lavoro stesso, con progetti, ambienti, team e chiavi, ma non all’interno di un ambiente. Creane una in :part1 :part2 :part3 alla radice della piattaforma.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'I token di accesso di questa app indicano :part1 come audience :part2. Quell’API deve accettare un token solo se la indica come destinataria.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'I token di accesso di questa app indicano come audience l’emittente di questo ambiente, :part1 :part2. Questo cambia quando l’app possiede un ambito di una delle API registrate.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Aggiungi un record TXT in :part1 :part2 con il valore riportato sotto, poi fai clic su Verifica. La propagazione delle modifiche DNS può richiedere qualche minuto.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Un’app registra il proprio catalogo tramite l’SDK.:part1 :part2 Puoi creare il ruolo ora e definirne il contenuto quando arrivano le chiavi.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Applicazioni che considerano questo ambiente attendibile come provider di identità SAML. Per consentire l’accesso con un account già esistente altrove, usa :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Le approvazioni riguardano le azioni dell’API di gestione. Questi ambiti sono gestiti da endpoint che non sono ancora azioni, quindi vengono eseguiti senza chiedere approvazione: :part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Le app indirizzano le persone alla registrazione con :part1 e chiedono a chi ha già effettuato l’accesso di creare un’organizzazione con :part2. Entrambe le opzioni sono disponibili solo mentre questa impostazione è attiva.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'La verifica viene richiesta esattamente come la richiede la tua app (:part1), seguendo tutte le relazioni di ereditarietà definite dallo schema.',
    'auth_settings_differ' => ':count impostazione è diversa da quella del tuo ambiente.|:count impostazioni sono diverse da quelle del tuo ambiente.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_fbee6c88' => 'Connettiti una sola volta alla radice della piattaforma, anziché una volta per ambiente. Con la tua identità, la connessione accede al tuo spazio di lavoro, a tutti i suoi ambienti che amministri e al tuo account. Uno strumento per gli ambienti usa un argomento :part1 :part2, mentre l’API REST usa un’intestazione :part3, per indicare dove agire. Può fare ciò che puoi fare tu, nei limiti che autorizzi, e ogni azione critica attende la tua approvazione sul tuo dispositivo.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Ogni nuovo account crea una propria organizzazione e ne diventa proprietario. Le app possono anche chiedere a chi ha effettuato l’accesso di crearne una con :part1 :part2.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Ogni organizzazione assegna alla persona un :part1, che stabilisce cosa può amministrare al suo interno, e un numero qualsiasi di :part2, che stabiliscono cosa può fare nelle sue app.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Ambiente «:part1» creato. Aggiungi :part2 dalle impostazioni dei domini dell’ambiente per verificarlo tramite DNS: un dominio non verificato non può esserne l’emittente.',
    'environments_nest_under_a_project_and_a_project_under_a_03ba63b6' => 'Gli ambienti appartengono a un progetto e ogni progetto a un :part1 :part2 :part3. Parti da lì per vedere tutte le risorse di uno spazio di lavoro. Due righe qui non hanno mai uno spazio di lavoro: :part4 è l’ambiente in cui viene eseguita questa installazione, che ospita gli operatori e le persone degli spazi di lavoro; un ambiente :part5 :part6 non ha invece alcun progetto, quindi non viene fatturato e nessuno spazio di lavoro può accedervi. Nessuno dei due casi è un errore da correggere in questa schermata, che non permette di riassegnarli.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Tutti i metodi con cui le persone accedono a :part1, se sono attivi e dove modificarli. Le organizzazioni possono applicare regole più restrittive:part2 :part3.',
    'every_workspace_environment_and_operator_on_part1_a_sus_e4247a2d' => 'Ogni spazio di lavoro, ambiente e operatore su :part1. Una sospensione, un nuovo ambiente o una modifica agli operatori effettuata qui si applica a tutti.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Feature flag «:part1» creato. Rimane disattivato per tutti finché una regola sottostante o il valore predefinito non lo attiva.',
    'framework_3cf574caed49' => 'Gli ambiti :value1 appartengono a un’API registrata i cui ambiti non sono consentiti a questo client. Un client appartenente a un’organizzazione può avere ambiti delle API della propria organizzazione e quelli delle API dell’ambiente che le organizzazioni sono autorizzate a richiedere.',
    'framework_43fd205dea6a' => 'L’ambito [:key] appartiene già a un’altra API in questo ambiente. Le chiavi degli ambiti sono univoche per ambiente, perché una richiesta di token identifica un ambito solo tramite la sua chiave.',
    'framework_47867973811e' => 'Sincronizzazione della directory con :provider non riuscita: :request ha raggiunto il limite di frequenza (HTTP :status). Numero di tentativi: :attempt.',
    'framework_5eb368b0fb37' => 'Workday: l’URL del report deve essere l’indirizzo del suo servizio web: …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'L’app [:clientId] deve avere lo stesso proprietario dell’API di cui applica le autorizzazioni. Collegarla inserirebbe i ruoli e le autorizzazioni di un proprietario nei token di un altro.',
    'framework_87da9891b0ad' => 'Sincronizzazione della directory con :provider non riuscita: :request non era disponibile (HTTP :status) dopo :attempt tentativi.',
    'framework_98eb4683e38b' => 'Sincronizzazione della directory con :provider non riuscita: :request non riuscita (HTTP :status): risorsa non trovata. Controlla l’account, il sottodominio o l’indirizzo del report.',
    'framework_a934fd6a0c26' => '[:origin] usa http, quindi la chiave e tutto ciò che la pagina fa con essa viaggerebbero in chiaro sulla rete. Usa https oppure, durante lo sviluppo, un host di loopback come http://localhost:3000.',
    'framework_b63785ee57fb' => 'Sincronizzazione della directory con :provider non riuscita: :request non riuscita (HTTP :status): le credenziali non hanno il permesso di leggere i dipendenti.',
    'framework_e5ca82ab9dff' => 'Sincronizzazione della directory con :provider non riuscita: :request non riuscita (HTTP :status): le credenziali sono state rifiutate.',
    'framework_fc1964a8e8c4' => 'Questo è l’ultimo segreto attivo del client [:clientId]. Esegui una rotazione per sostituirlo; revocarlo impedirebbe al client di autenticarsi.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Se quell’endpoint è :part1, le persone non ancora migrate non possono accedere. Chi è già stato migrato non è interessato.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'Nell’ordine in cui vengono mostrati alle persone. Disattivare qui uno dei metodi dell’ambiente rimuove solo il pulsante da questa pagina: non impedisce di usarlo per accedere altrove. Per rendere il tuo provider di identità l’unico metodo di accesso, rendi obbligatorio l’SSO in :part1 :part2.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Le chiavi iniziano con questo prefisso, così una chiave trovata in un log identifica questa app: :part1 :part2. Da 2 a 16 lettere minuscole o cifre, seguite da :part3 oppure :part4 :part5, univoche in questo ambiente. Impostare un prefisso abilita le chiavi. Cancellarlo impedisce di crearne di nuove; quelle già create funzionano fino alla revoca.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Elencare i feature flag con le regole di targeting e valutare ogni flag per un utente di un’organizzazione. È ciò che richiede il backend di un’app quando non dispone di un token.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Elencare le directory (SCIM, Google Workspace, Microsoft Entra) che sincronizzano le persone, i relativi gruppi e gli errori di sincronizzazione, senza mai esporre token bearer o credenziali dei provider.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Elencare le connessioni SAML e OIDC usate dalle organizzazioni per accedere e i domini e-mail che vi indirizzano le persone, senza mai esporre certificati, segreti client o chiavi di firma.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Elencare i provider esterni a cui le persone possono collegare i propri account, le app autorizzate a usare temporaneamente i token e le persone collegate, senza mai esporre segreti client o token.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Creare e revocare link monouso al portale di amministrazione. Permettono all’amministratore IT di un’organizzazione di configurare SSO, domini o sincronizzazione della directory senza un account. Ogni nuovo link viene mostrato una sola volta.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Non ci sono ancora ruoli a cui associare i dati. Definiscine uno in :part1 :part2 oppure lascia che un’app dichiari i propri.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_462fe672' => 'Nessuno in questa organizzazione ha creato una chiave per una delle sue app. Gli utenti creano le proprie chiavi in Il mio account, per un’app che abbia abilitato le chiavi API dei membri nelle impostazioni: :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Nessuno ha effettuato l’accesso a un’app impersonando una delle sue persone. Avvia una sessione dalla pagina di una persona in :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Solo la console può assegnare :part1 a un’app: non una chiave di gestione né un agente che agisce per te. Concedilo nella console, nella pagina Scope dell’app.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Sono disponibili solo le azioni che puoi eseguire personalmente in :part1. Se in seguito perdi un’autorizzazione, la perde anche la chiave.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Inserisce le chiavi dei feature flag attivi per la persona nell’organizzazione a cui ha effettuato l’accesso nel token di accesso, nel token ID e in UserInfo come claim `feature_flags`.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Inserisce i RUOLI della persona nel token ID con il nome `groups`, atteso da Kubernetes, Grafana, Vault e molte applicazioni SaaS meno recenti. In questa console non esiste un oggetto chiamato gruppo. Crea un ruolo con il nome previsto dall’app e verrà incluso in quel campo.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Leggere la modalità di Radar, le regole integrate e personalizzate, le liste di autorizzazione e blocco e la vista delle decisioni: perché un accesso o una registrazione è stato consentito, ha richiesto una verifica aggiuntiva o è stato bloccato. Gli indirizzi IP ed e-mail contenuti nelle decisioni non vengono mai esposti.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Leggere gli eventi di audit inviati dalla tua app e le relative esportazioni, verificare la catena di eventi di un’organizzazione e consultare gli schemi e le regole di conservazione applicabili.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Leggere lo schema di autorizzazione e le tuple ed eseguire verifiche dei permessi e query di elenco, per esempio «questo utente può modificare questo documento?» oppure «quali documenti può vedere?». Solo le autorizzazioni necessarie al backend di un’app per controllare l’accesso.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Sostituisci lo schema di autorizzazione, ovvero i tipi di risorsa e il modo in cui viene determinata ogni relazione. Cambia immediatamente la risposta a ogni verifica in questo ambiente.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Ruoli validi nell’intero ambiente, in ogni organizzazione e anche per chi non appartiene a nessuna. Le organizzazioni non li vedono mai.:part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Ambiente sandbox, solo per i test. Questo :part1 è il tuo accesso di produzione e non vengono inviate email reali.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Scope «:part1» rimosso. Le app che lo avevano lo mantengono come scope digitato, che non dà più accesso a questa API.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'Sono mostrati i primi :part1. Cerca per trovare gli altri: tutto ciò che hai già selezionato rimane nell’elenco.',
    'sms_allowed_country_count' => 'Accettato come secondo fattore in :count paese.|Accettato come secondo fattore in :count paesi.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Una persona che :part1 non viene mai inviata: la sua password è quella di Cbox ID e il vecchio sistema non ha alcuna voce in capitolo.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Quando una persona accede ed è :part1, la sua email e la sua password vengono inviate a quell’endpoint. Se la risposta è positiva, viene creata qui e non viene più inviata.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Archiviare, ruotare e revocare le credenziali di servizi esterni, e concedere o ritirare a un’app il diritto di usarle temporaneamente. Questo non riguarda gli ambiti vault.manage / vault.lease presenti nel token dell’app stessa.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Ogni richiesta contiene :part1 :part2, una chiave di gestione di questo ambiente.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Hai dubbi su uno di questi punti? Ogni pagina della console ha un :part1 :part2 :part3 accanto al titolo, con una spiegazione breve e un link alla guida completa.',
    'suspension_is_the_only_lever_here_and_it_is_reversible_84455a59' => 'Qui puoi solo sospendere uno spazio di lavoro o riattivarlo. Nulla in questa pagina elimina uno spazio di lavoro o cancella i suoi dati. L’installazione contiene anche ambienti senza spazio di lavoro: la radice della piattaforma e gli eventuali ambienti rimasti senza associazione. Entrambi sono identificati chiaramente in :part1 :part2.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Questa pagina modifica solo la sospensione, che può essere annullata. Selezionare e aprire un ambiente cambia solo la vista della console, senza modificare nessuno degli ambienti.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'I codici SMS inviati a :part1 smetteranno di funzionare. L’app di autenticazione, le passkey e i codici di recupero non vengono modificati. Se il numero era l’unico secondo fattore, l’account sarà protetto soltanto dalla password finché non verrà configurato un nuovo fattore.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Quel certificato è già scaduto (:part1). Scarica quello attuale dal tuo provider di identità.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Questo favicon non può essere usato. Invia l’immagine stessa come URI data: codificato in base64 (data:image/png;base64,…). Gli URL di immagini esterne non sono accettati: ogni visitatore carica l’immagine della pagina di accesso e il server esterno riceverebbe così informazioni sui visitatori.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Sono state inviate molte email. Riprova tra :part1 secondi oppure controlla nel frattempo la cartella spam.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Tutti i punti dell’elenco sono completati. D’ora in poi tornerai nella console soprattutto quando ne avrai bisogno. Due sezioni meritano un controllo regolare: :part1 :part2 :part3 e :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Questo logo non può essere usato. Invia l’immagine stessa come URI data: codificato in base64 (data:image/png;base64,…). Gli URL di immagini esterne non sono accettati: ogni visitatore carica l’immagine della pagina di accesso e il server esterno riceverebbe così informazioni sui visitatori.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'I domini e-mail di cui le tue organizzazioni hanno dichiarato la proprietà. Un dominio verificato indirizza tutte le persone con un indirizzo su quel dominio alla connessione dell’organizzazione: :part1 :part2. Ogni dominio viene verificato nella pagina della sua organizzazione.',
    'the_metadata_value_for_part1_must_be_text_63748730' => 'Il valore dei metadati per [:part1] deve essere testo.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Le voci più recenti nella cronologia di :part1.',
    'the_people_in_part1_cf74b32e' => 'Le persone in :part1.',
    'the_people_on_part1_and_what_each_may_reach_474ab0a4' => 'Le persone in :part1 e ciò a cui ciascuna può accedere.',
    'the_platform_s_own_environment_on_part1_how_every_works_07c8a7ac' => 'L’ambiente della piattaforma stessa su :part1: permette a tutti i proprietari degli spazi di lavoro e agli operatori di accedere a Cbox ID e alle console di tutti gli ambienti. Una modifica si applica a tutti questi accessi.',
    'the_role_part1_belongs_to_one_organization_and_cannot_b_e2bba059' => 'Il ruolo [:part1] appartiene a un’organizzazione e non può essere assegnato ovunque.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Il ruolo [:part1] non può essere assegnato in questa organizzazione: appartiene a un’altra organizzazione o a un’app che questa organizzazione non può usare.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Lo stesso codice, passo dopo passo, con la disconnessione::part1 :part2 .',
    'the_scim_base_url_must_be_a_public_address_part1_4cfd762c' => 'L’URL di base SCIM deve essere un indirizzo pubblico. (:part1)',
    'the_secret_was_shown_once_when_the_app_was_created_part_7a1fcce3' => 'Il segreto è stato mostrato una sola volta, alla creazione dell’app.:part1 :part2 :part3 per ottenerne uno nuovo.',
    'the_whole_environment_part1_6c96bfa7' => 'L’intero ambiente :part1',
    'theme_this_organization_s_sign_in_page_its_team_signs_i_cceda878' => 'Personalizza la pagina di accesso di questa organizzazione. Il team accede da :part1 :part2 .',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'Non c’è alcun segreto client da incollare. :part1 richiede invece un’asserzione firmata, che generiamo con la chiave sopra per ogni accesso e rinnoviamo molto prima della scadenza.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Non c’è ancora un ruolo da assegnare. Definiscine uno nella pagina :part1 :part2 :part3 oppure lascia che un’app dichiari i propri nel manifest.',
    'these_apply_to_every_organization_in_part1_not_only_par_ac56590d' => 'Questi si applicano a tutte le organizzazioni in :part1, non solo a :part2 .',
    'these_are_its_own_credentials_for_that_environment_s_co_a68e7d01' => 'Queste sono le sue credenziali, per la configurazione di quell’ambiente. :part1',
    'these_are_the_buttons_on_part1_how_every_workspace_owne_5c0655c0' => 'Questi sono i pulsanti di :part1 usati dai proprietari degli spazi di lavoro e dagli operatori per accedere a Cbox ID e quindi alle console di tutti gli ambienti, i cui amministratori usano account Cbox ID. Registra presso ogni provider l’URI di reindirizzamento indicato. Si trova in :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Questi pulsanti sono destinati alle persone che accedono alle tue app, nelle pagine di accesso di :part1 :part2. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'La persona diventa proprietaria di :part1 e tu diventi amministratore. Solo il nuovo proprietario può restituirti la proprietà.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Questa app possiede ambiti di più API: :part1 :part2. Un token riguarda una sola API alla volta, quindi l’app indica quella desiderata con il parametro :part3. Una richiesta di ambiti di due API contemporaneamente viene rifiutata.',
    'this_console_is_your_workspace_its_projects_team_keys_a_66180b31' => 'Questa console è il tuo spazio di lavoro: progetti, team, chiavi e fatturazione. I metodi di accesso alle tue app, inclusa :part1, vengono configurati per ogni ambiente nella relativa console.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Questa credenziale richiede l’approvazione di una persona per l’azione, ma non è registrato nessuno che possa approvarla. Esegui l’azione dalla console oppure crea lì una chiave il cui proprietario possa approvare.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Questa installazione invia SMS solo a :part1, quindi i numeri in :part2 non possono ricevere codici finché non vengono inclusi in CBOX_ID_SMS_ALLOWED_COUNTRIES.',
    'this_environment_s_issuer_discovery_and_jwks_are_served_06e9c844' => 'L’emittente, il documento di discovery e il JWKS di questo ambiente sono disponibili su :part1 :part2. Punta l’host al tuo ingress e termina TLS lì.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'L’emittente di questo ambiente: quello da cui un SDK esegue la discovery e che viene indicato nella claim :part1.',
    'this_person_is_the_only_owner_of_part1_organization_s_p_662dfa99' => 'Questa persona è l’unico proprietario di :part1 organizzazioni: :part2. Trasferisci la proprietà prima di eliminarla.',
    'this_will_allow_part1_to_6ac64554' => 'Questo consentirà a :part1 di',
    'to_answer_a_right_to_erasure_request_use_part1_at_the_f_536cbf09' => 'Per rispondere a una richiesta di cancellazione, usa invece :part1 in fondo a questa pagina.',
    'two_factor_authentication_part1_8c022f7b' => 'Autenticazione a due fattori :part1',
    'two_factor_part1_part2_d0a29caf' => 'Due fattori: :part1. :part2',
    'type_part1_to_confirm_25ad7324' => 'Digita :part1 per confermare',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Gli scope digitati (:part1) non hanno un proprietario: vengono trasmessi così come sono e mai con l’audience di un’API registrata.',
    'unchanged_by_anything_here_so_nothing_to_update_in_part_75ac8c0d' => 'Le modifiche qui non influiscono su questo, quindi non c’è nulla da aggiornare in :part1.',
    'updated_part1_275f47a3' => 'Aggiornato :part1',
    'user_created_a_sign_in_link_is_on_its_way_to_part1_340287fa' => 'Utente creato. È in corso l’invio di un link di accesso a :part1.',
    'verification_email_sent_to_part1_254c8e75' => 'E-mail di verifica inviata a :part1.',
    'via_part1_b3f55fad' => 'tramite :part1',
    'wants_to_act_on_behalf_of_part1_5e98fe61' => 'vuole agire per conto di :part1',
    'we_could_not_reach_part1_at_part2_check_the_details_par_c1087a18' => 'Impossibile raggiungere :part1 all’indirizzo :part2. Controlla i dati. (:part3)',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Non è stato possibile inviare l’e-mail perché questa installazione non riesce a raggiungere il server di posta. Riprova più tardi. Un amministratore può anche confermare il tuo indirizzo con `php artisan cbox-id:users:confirm-email`.',
    'we_have_sent_a_few_links_already_try_again_in_part1_sec_a84fe552' => 'Abbiamo già inviato alcuni link. Riprova tra :part1 secondi oppure controlla nel frattempo la cartella spam.',
    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Abbiamo inviato un link a :part1. Appena lo apri viene creato il tuo primo ambiente: il provider di identità in produzione, con accesso, utenti e chiavi di firma propri. Poi torni direttamente qui. Il link è valido per 24 ore.',
    'webhook_delivered_at' => ' · consegnato :time',
    'webhook_retry_at' => ' · nuovo tentativo :time',
    'welcome_back_part1_3c339e48' => 'Bentornato, :part1',
    'what_is_part1_00d3f3e7' => 'Che cos’è :part1?',
    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Ciò che amministri e i dati necessari alle tue app per l’integrazione. :part1',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Le azioni in attesa di approvazione. L’agente riceve una risposta 202 con un codice breve. Approvi dal telefono o in :part1 :part2 e l’agente ripete la richiesta una sola volta.',
